import { useEffect, useRef, useState } from 'react';
import { MESSAGE_LIST_MAIN_PANEL_CLASS } from '../../MessageListMainPanel';
import { UNREAD_MESSAGE_SEPARATOR_CLASS } from '../../UnreadMessagesSeparator';
import type { MessagePaginatorState, UnreadSnapshotState } from 'stream-chat';
import { useStateStore } from '../../../../store';
import { useMessagePaginator } from '../../../../hooks';

const targetScrolledAboveVisibleContainerArea = (
  element: Element,
  container?: Element,
) => {
  const { bottom: targetBottom } = element.getBoundingClientRect();
  const containerTop = container?.getBoundingClientRect().top ?? 0;
  return targetBottom < containerTop;
};

const targetScrolledBelowVisibleContainerArea = (
  element: Element,
  container: Element,
) => {
  const { top: targetTop } = element.getBoundingClientRect();
  const { bottom: containerBottom } = container.getBoundingClientRect();
  return targetTop > containerBottom;
};

export type UseUnreadMessagesNotificationParams = {
  /** Scroll container, used as the IntersectionObserver root and for the initial visibility. */
  listElement: HTMLDivElement | null;
  isMessageListScrolledToBottom: boolean;
  showAlways: boolean;
};

const messagePaginatorStateSelector = (state: MessagePaginatorState) => ({
  messages: state.items ?? [],
});

const unreadStateSnapshotSelector = (state: UnreadSnapshotState) => ({
  unreadCount: state.unreadCount,
});

export const useUnreadMessagesNotification = ({
  isMessageListScrolledToBottom,
  listElement,
  showAlways,
}: UseUnreadMessagesNotificationParams) => {
  const messagePaginator = useMessagePaginator();

  const { messages } = useStateStore(
    messagePaginator.state,
    messagePaginatorStateSelector,
  );

  const { unreadCount } = useStateStore(
    messagePaginator.unreadStateSnapshot,
    unreadStateSnapshotSelector,
  );
  const [show, setShow] = useState(false);
  // Where the unread separator sits relative to the viewport: below it after scrolling up past it.
  // `undefined` while no separator is rendered (the unread messages are outside the loaded window).
  const [unreadIsBelow, setUnreadIsBelow] = useState<boolean | undefined>(undefined);
  const isScrolledAboveTargetTop = useRef(false);
  const intersectionObserverIsSupported = typeof IntersectionObserver !== 'undefined';

  useEffect(() => {
    if (!(unreadCount && intersectionObserverIsSupported)) {
      setShow(false);
      return;
    }

    const scrollRoot = listElement ?? null;
    if (!scrollRoot) {
      const [msgListPanel] = document.getElementsByClassName(
        MESSAGE_LIST_MAIN_PANEL_CLASS,
      );
      if (!msgListPanel) return;
      const [observedTarget] = document.getElementsByClassName(
        UNREAD_MESSAGE_SEPARATOR_CLASS,
      );
      if (!observedTarget) {
        setShow(unreadCount > 0);
        setUnreadIsBelow(undefined);
      }
      return;
    }

    // Only this list's separator: with several lists on screen (channels side by side), the first one
    // in the page can belong to another list.
    const [observedTarget] = scrollRoot.getElementsByClassName(
      UNREAD_MESSAGE_SEPARATOR_CLASS,
    );
    if (!observedTarget) {
      setShow(unreadCount > 0);
      setUnreadIsBelow(undefined);
      return;
    }

    const scrolledBelowSeparator = targetScrolledAboveVisibleContainerArea(
      observedTarget,
      scrollRoot,
    );
    const scrolledAboveSeparator = targetScrolledBelowVisibleContainerArea(
      observedTarget,
      scrollRoot,
    );

    setShow(
      showAlways
        ? scrolledBelowSeparator || scrolledAboveSeparator
        : scrolledBelowSeparator,
    );
    setUnreadIsBelow(scrolledAboveSeparator);

    const observer = new IntersectionObserver(
      (elements) => {
        if (!elements.length) return;
        const entry = elements[0];
        const { boundingClientRect, isIntersecting, rootBounds } = entry;
        if (isIntersecting) {
          setShow(false);
          return;
        }
        const rootTop = rootBounds?.top ?? 0;
        const separatorIsAboveContainerTop = boundingClientRect.bottom < rootTop;
        setShow(showAlways || separatorIsAboveContainerTop);
        setUnreadIsBelow(!separatorIsAboveContainerTop);
        isScrolledAboveTargetTop.current = separatorIsAboveContainerTop;
      },
      { root: scrollRoot },
    );
    observer.observe(observedTarget);

    return () => {
      observer.disconnect();
    };
  }, [
    intersectionObserverIsSupported,
    listElement,
    isMessageListScrolledToBottom,
    messages,
    showAlways,
    unreadCount,
  ]);

  useEffect(() => {
    // `Element.scrollTo()` does not trigger the IntersectionObserver, so a list scrolled to the
    // bottom by another component can still be recorded as scrolled above the unread separator.
    if (
      unreadCount &&
      isMessageListScrolledToBottom &&
      isScrolledAboveTargetTop.current
    ) {
      setShow(true);
      isScrolledAboveTargetTop.current = false;
    }
  }, [isMessageListScrolledToBottom, unreadCount]);

  return { show: show && intersectionObserverIsSupported, unreadIsBelow };
};
