import { CheckSignIcon } from '../../MessageComposer/icons';
import React from 'react';
import {
  useComponentContextIcons,
  useMessageComposerContext,
  useTranslationContext,
} from '../../../context';
import { isRecording, isStopped } from './recordingStateIdentity';
import { Button } from '../../Button';
import { useNotificationApi } from '../../Notifications';
import { UploadProgressIndicator } from '../../Loading/UploadProgressIndicator';

const ToggleRecordingButton = () => {
  const { IconPauseFill, IconVoice } = useComponentContextIcons();
  const { t } = useTranslationContext();
  const {
    recordingController: { recorder, recordingState },
  } = useMessageComposerContext();

  const recording = isRecording(recordingState);

  return (
    <Button
      appearance='outline'
      aria-label={
        recording
          ? t(
              'mediaRecorder.audioRecorderRecording.pauseRecording.ariaLabel',
              'Pause recording',
            )
          : t(
              'mediaRecorder.audioRecorderRecording.resumeRecording.ariaLabel',
              'Resume recording',
            )
      }
      circular
      className='str-chat__audio_recorder__toggle-recording-button'
      // A stopped recording cannot be resumed.
      disabled={isStopped(recordingState)}
      onClick={() => (recording ? recorder?.pause() : recorder?.resume())}
      size='sm'
      variant='secondary'
    >
      {recording ? <IconPauseFill /> : <IconVoice />}
    </Button>
  );
};

export const AudioRecorderRecordingControls = () => {
  const { IconDelete } = useComponentContextIcons();
  const { addNotification } = useNotificationApi();
  const { t } = useTranslationContext();
  const {
    recordingController: { completeRecording, recorder, recording, recordingState },
  } = useMessageComposerContext();
  const isUploadingFile = recording?.localMetadata?.uploadState === 'uploading';
  const uploadProgress = recording?.localMetadata?.uploadProgress;

  if (!recorder) return null;

  return (
    <div className='str-chat__audio_recorder__recording-controls'>
      {!isRecording(recordingState) && (
        <Button
          appearance='ghost'
          aria-label={t(
            'mediaRecorder.audioRecorderRecording.cancelRecording.ariaLabel',
            'Cancel recording',
          )}
          circular
          className='str-chat__audio_recorder__cancel-button'
          data-testid={'cancel-recording-audio-button'}
          disabled={isUploadingFile}
          onClick={() => {
            recorder.cancel();
            addNotification({
              emitter: 'AudioRecorder',
              message: t(
                'mediaRecorder.audioRecorderRecording.voiceMessageDeleted.text',
                'Voice message deleted',
              ),
              severity: 'info',
              type: 'audioRecording:cancel:success',
            });
          }}
          size='sm'
          variant='secondary'
        >
          <IconDelete />
        </Button>
      )}
      <ToggleRecordingButton />
      <Button
        appearance='solid'
        aria-label={t(
          'mediaRecorder.audioRecorderRecording.completeRecording.ariaLabel',
          'Complete recording',
        )}
        circular
        className='str-chat__audio_recorder__stop-button'
        data-testid='audio-recorder-stop-button'
        onClick={completeRecording}
        size='sm'
        variant='primary'
      >
        {isUploadingFile ? (
          <UploadProgressIndicator uploadProgress={uploadProgress} />
        ) : (
          <CheckSignIcon />
        )}
      </Button>
    </div>
  );
};
